-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Sicherheitsberichte dienen der Risikoanalyse im Anwendersupport. b) Sicherheitsberichte sind nur bei Vorfällen erforderlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Analyse ja, regelmäßig nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Sicherheitsberichte müssen vertraulich sein. b) Sicherheitsberichte ersetzen Sicherheitsmaßnahmen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Vertraulich ja, Ergänzung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Sicherheitsberichte dokumentieren Sicherheitsvorfälle. b) Sicherheitsberichte sind nur für externe Prüfer gedacht.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Dokumentation ja, intern genutzt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Sicherheitsberichte helfen bei der Prozessverbesserung. b) Sicherheitsberichte werden täglich erstellt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Verbesserung ja, nicht täglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Sicherheitsberichte enthalten Maßnahmenbeschreibungen. b) Sicherheitsberichte sind für alle Mitarbeiter zugänglich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Maßnahmen ja, Zugang begrenzt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

